CREATE TABLE `historical_exchange_rates` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	`deleted_at` integer,
	`source_instrument_id` integer NOT NULL,
	`target_instrument_id` integer NOT NULL,
	`rate_date` text NOT NULL,
	`rate` real NOT NULL,
	FOREIGN KEY (`source_instrument_id`) REFERENCES `instruments`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`target_instrument_id`) REFERENCES `instruments`(`id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE UNIQUE INDEX `historical_exchange_rates_source_instrument_id_target_instrument_id_rate_date_unique` ON `historical_exchange_rates` (`source_instrument_id`,`target_instrument_id`,`rate_date`);--> statement-breakpoint
CREATE INDEX `historical_exchange_rates_lookup_idx` ON `historical_exchange_rates` (`source_instrument_id`,`target_instrument_id`,`rate_date` DESC) WHERE `deleted_at` IS NULL;--> statement-breakpoint
