INSERT OR IGNORE INTO historical_exchange_rates (source_instrument_id, target_instrument_id, rate_date, rate)
SELECT source.id, target.id, historical_uah_rate_seed.rate_date, historical_uah_rate_seed.rate
FROM historical_uah_rate_seed
INNER JOIN instruments source ON source.code = historical_uah_rate_seed.source_code
INNER JOIN instruments target ON target.code = historical_uah_rate_seed.target_code;

--> statement-breakpoint
ALTER TABLE `transaction_entries` ADD `base_instrument_id` integer REFERENCES instruments(id) ON DELETE set null;--> statement-breakpoint
ALTER TABLE `transaction_entries` ADD `base_exchange_rate` real;--> statement-breakpoint
ALTER TABLE `transaction_entries` ADD `base_amount` integer;--> statement-breakpoint
CREATE INDEX `transaction_entries_base_valuation_idx` ON `transaction_entries` (`base_instrument_id`,`base_amount`) WHERE `deleted_at` IS NULL;
